head.b:skin:
/* Pilot theme: the Pages stylesheet remains the design reference.
   Vendor this CSS into the Blogger theme before final migration. */
@import url('https://oneplate-ai.github.io/styles.css');
.blogger-shell { width: min(1120px, calc(100% - 48px)); margin: 0 auto; }
.blogger-post-meta { color: var(--muted); font-size: 12px; margin: 0 0 18px; }
.blogger-labels { display: flex; flex-wrap: wrap; gap: 8px; margin: 18px 0 28px; }
.blogger-labels a { color: var(--green); font-size: 12px; text-decoration: none; }
.blogger-language { margin-left: 10px; }
.blogger-language a { border: 1px solid var(--line); border-radius: 999px; padding: 7px 10px; }
.blogger-shell .post-title { font-family: var(--display); font-size: clamp(32px, 5vw, 52px); font-weight: 400; letter-spacing: -.065em; line-height: 1.3; }
.blog-post { min-width: 0; }
.blog-post + .blog-post { margin-top: 72px; padding-top: 48px; border-top: 1px solid var(--line); }
.blogger-shell .post-body { font-size: 15px; line-height: 1.7; }
.blogger-shell .post-body img { max-width: 100%; height: auto; }
.blogger-shell .post-body .summary { padding: 18px 20px; border-left: 3px solid var(--accent); background: #fbf8f1; }
.blogger-shell .post-body .verification-note { margin: 20px 0 28px; padding: 10px 14px; border-left: 2px solid #d6ddd2; background: #fafbf8; color: #758075; font-size: 13px; }
@media (max-width: 720px) {
  .blogger-shell { width: min(100% - 32px, 1120px); }
}
